17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.util.UriComponentsBuilder;
44	
45	import jakarta.transaction.Transactional;
46	
47	/**
48	 * @author Vitaliy Fedoriv
49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    private final ClinicService clinicService;
57	
58	    private final OwnerMapper ownerMapper;
59	
60	    private final PetMapper petMapper;
61	
62	    private final VisitMapper visitMapper;
63	
64	    public OwnerRestControllerV1(ClinicService clinicService,
65	                                 OwnerMapper ownerMapper,
66	                                 PetMapper petMapper,
67	                                 VisitMapper visitMapper) {
68	        this.clinicService = clinicService;
69	        this.ownerMapper = ownerMapper;
70	        this.petMapper = petMapper;
71	        this.visitMapper = visitMapper;
72	    }
73	
74	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
75	    @Override
76	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
77	        Collection<Owner> owners;
78	        if (lastName != null) {
79	            owners = this.clinicService.findOwnerByLastName(lastName);
80	        } else {
81	            owners = this.clinicService.findAllOwners();
82	        }
83	        if (owners.isEmpty()) {
84	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
85	        }
86	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
92	        Owner owner = this.clinicService.findOwnerById(ownerId);
93	        if (owner == null) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
102	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
103	        if (normalizedTelephone == null) {
104	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
105	        }
106	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
107	            return new ResponseEntity<>(HttpStatus.CONFLICT);
108	        }
109	        HttpHeaders headers = new HttpHeaders();
110	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
111	        owner.setTelephone(normalizedTelephone);
112	        this.clinicService.saveOwner(owner);
113	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
114	        headers.setLocation(UriComponentsBuilder.newInstance()
115	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
116	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
122	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
123	        if (currentOwner == null) {
124	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
125	        }
126	        currentOwner.setAddress(ownerFieldsDto.getAddress());
127	        currentOwner.setCity(ownerFieldsDto.getCity());
128	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
129	        currentOwner.setLastName(ownerFieldsDto.getLastName());
130	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
131	        this.clinicService.saveOwner(currentOwner);
132	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
133	    }
134	
135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Transactional
137	    @Override
138	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
139	        Owner owner = this.clinicService.findOwnerById(ownerId);
140	        if (owner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        this.clinicService.deleteOwner(owner);
144	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Override
149	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
150	        Owner owner = this.clinicService.findOwnerById(ownerId);
151	        if (owner == null) {
152	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
153	        }
154	        HttpHeaders headers = new HttpHeaders();
155	        Pet pet = petMapper.toPet(petFieldsDto);
156	        owner.setId(ownerId);
157	        pet.setOwner(owner);
158	        pet.getType().setName(null);
159	        this.clinicService.savePet(pet);
160	        PetDto petDto = petMapper.toPetDto(pet);
161	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
162	            .buildAndExpand(pet.getId()).toUri());
163	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Override
168	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
169	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
170	        if (currentOwner != null) {
171	            Pet currentPet = this.clinicService.findPetById(petId);
172	            if (currentPet != null) {
173	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
174	                currentPet.setName(petFieldsDto.getName());
175	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
176	                this.clinicService.savePet(currentPet);
177	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
178	            }
179	        }
180	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
181	    }
182	
183	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
184	    @Override
185	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
186	        HttpHeaders headers = new HttpHeaders();
187	        Visit visit = visitMapper.toVisit(visitFieldsDto);
188	        Pet pet = new Pet();
189	        pet.setId(petId);
190	        visit.setPet(pet);
191	        this.clinicService.saveVisit(visit);
192	        VisitDto visitDto = visitMapper.toVisitDto(visit);
193	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
194	            .buildAndExpand(visit.getId()).toUri());
195	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
196	    }
197	
198	
199	    /**
200	     * Normalize a telephone number for owner creation by removing every non-digit
201	     * character. Returns the resulting value only when it is exactly 10 digits;
202	     * otherwise returns {@code null} to signal a bad request.
203	     */
204	    private String normalizeTelephone(String telephone) {
205	        if (telephone == null) {
206	            return null;
207	        }
208	        String digits = telephone.replaceAll("\\D", "");
209	        return digits.length() == 10 ? digits : null;
210	    }
211	
